UPDATE page_contents SET value = replace(value, 'Chaque pôle est une association animée par une équipe salariée et un conseil d''administration issu de ses adhérents. Les compositions publiées sont celles du conseil d''administration 2021 pour le Pôle ESS Pays de Morlaix et 2025 pour le Pôle ESS Pays de Cornouaille. Pour joindre un pôle, passez par la page [Contact](/#contact).', 'Chaque pôle est une association animée par une équipe salariée et un conseil d''administration issu de ses adhérents. Pour joindre un pôle, passez par la page [Contact](/#contact).'), updated_at = CURRENT_TIMESTAMP WHERE page_key = 'equipe' AND section_key = 'presentation' AND field_key = 'body';
